(()=>{const title=document.querySelector('.hero h1');if(title){let i=0;title.setAttribute('aria-label',[...title.childNodes].map(node=>node.nodeName==='BR'?' ':node.textContent).join('').replace(/\s+/g,' ').trim());const split=node=>{[...node.childNodes].forEach(child=>{if(child.nodeType===3){const frag=document.createDocumentFragment();child.textContent.split(/( +)/).forEach(part=>{if(!part)return;if(/^ +$/.test(part)){frag.append(' ');return}const word=document.createElement('span');word.className='hw';word.setAttribute('aria-hidden','true');[...part].forEach(char=>{const letter=document.createElement('span');letter.className='hl';letter.style.setProperty('--i',i++);letter.textContent=char;word.append(letter)});frag.append(word)});child.replaceWith(frag)}else if(child.nodeType===1&&child.tagName!=='BR')split(child)})};split(title)}const slogan=document.querySelector('.c-slogan');if(slogan){if(!('IntersectionObserver'in window)){slogan.classList.add('in');return}const io=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){slogan.classList.add('in');io.disconnect()}}),{threshold:.3});io.observe(slogan)}})();
